create table nfse_issuers(id uuid primary key default gen_random_uuid(),office_id uuid not null references offices on delete cascade,client_id uuid references clients,tax_id text not null,legal_name text not null,municipal_registration text,municipality_ibge text not null check(municipality_ibge~'^[0-9]{7}$'),tax_regime text not null,dps_series text not null default '1',enabled boolean not null default false,created_at timestamptz not null default now(),unique(office_id,tax_id));
create table nfse_profile_issuer_access(profile_id uuid not null references profiles on delete cascade,issuer_id uuid not null references nfse_issuers on delete cascade,allowed boolean not null default true,primary key(profile_id,issuer_id));
create table nfse_service_profiles(id uuid primary key default gen_random_uuid(),office_id uuid not null references offices on delete cascade,issuer_id uuid not null references nfse_issuers on delete cascade,name text not null,national_code text not null,municipal_code text,nbs_code text,description text not null,taxation jsonb not null default '{}',valid_from date not null,valid_to date,fiscal_reviewed_at timestamptz,version int not null default 1,unique(issuer_id,name,version));
create table nfse_takers(id uuid primary key default gen_random_uuid(),office_id uuid not null references offices on delete cascade,issuer_id uuid not null references nfse_issuers on delete cascade,tax_id text not null,legal_name text not null,email text,address jsonb not null default '{}',created_at timestamptz not null default now(),unique(issuer_id,tax_id));
create table nfse_certificates(id uuid primary key default gen_random_uuid(),office_id uuid not null references offices on delete cascade,issuer_id uuid not null references nfse_issuers on delete cascade,custody_provider text not null,custody_reference text not null unique,key_version text not null,fingerprint_sha256 text not null,subject_tax_id text not null,not_before timestamptz not null,not_after timestamptz not null,status text not null check(status in ('active','replaced','expired','revoked')),created_at timestamptz not null default now());
create unique index nfse_one_active_certificate on nfse_certificates(issuer_id) where status='active';
create table nfse_sequences(office_id uuid not null references offices on delete cascade,issuer_id uuid not null references nfse_issuers on delete cascade,environment smallint not null check(environment=2),series text not null,next_number bigint not null check(next_number>0),primary key(issuer_id,environment,series));
create table nfse_invoices(id uuid primary key default gen_random_uuid(),office_id uuid not null references offices on delete cascade,issuer_id uuid not null references nfse_issuers,taker_id uuid not null references nfse_takers,service_profile_id uuid not null references nfse_service_profiles,environment smallint not null default 2 check(environment=2),status text not null default 'draft' check(status in ('draft','queued','signing','transmitting','unknown','reconciling','authorized','rejected','technical_failure','persistence_pending')),competence date not null,amount numeric(14,2) not null check(amount>0),description text not null,series text,dps_number bigint,dps_id text,official_key text,snapshot jsonb,content_hash text,idempotency_key text not null,created_by uuid not null references profiles,created_at timestamptz not null default now(),unique(office_id,issuer_id,environment,idempotency_key),unique(issuer_id,environment,series,dps_number),unique(dps_id));
create table nfse_jobs(id uuid primary key default gen_random_uuid(),office_id uuid not null references offices on delete cascade,invoice_id uuid not null references nfse_invoices on delete cascade,kind text not null check(kind in ('issue','consult','reconcile')),status text not null default 'queued' check(status in ('queued','claimed','done','failed','cancelled')),available_at timestamptz not null default now(),claimed_by text,lease_until timestamptz,attempts int not null default 0,created_at timestamptz not null default now(),unique(invoice_id,kind));
create table nfse_attempts(id uuid primary key default gen_random_uuid(),office_id uuid not null references offices on delete cascade,invoice_id uuid not null references nfse_invoices on delete cascade,job_id uuid references nfse_jobs,classification text not null,request_hash text,response_hash text,http_status int,correlation_id text,safe_details jsonb not null default '{}',created_at timestamptz not null default now());
create table nfse_files(id uuid primary key default gen_random_uuid(),office_id uuid not null references offices on delete cascade,invoice_id uuid not null references nfse_invoices on delete cascade,kind text not null check(kind in ('signed_dps','official_xml','raw_response')),storage_path text not null unique,sha256 text not null,size_bytes bigint not null check(size_bytes>=0),created_at timestamptz not null default now());

create or replace function reserve_nfse_dps(invoice uuid) returns table(series text,dps_number bigint) language plpgsql security definer set search_path=public,pg_temp as $$ declare n nfse_invoices; s text; v bigint; begin select * into n from nfse_invoices where id=invoice for update; if n.id is null or n.status<>'draft' or n.office_id<>current_office() or not has_module('nfse') then raise exception 'invoice_not_reservable' using errcode='42501'; end if; select dps_series into s from nfse_issuers where id=n.issuer_id and enabled; if s is null then raise exception 'issuer_not_ready'; end if; insert into nfse_sequences values(n.office_id,n.issuer_id,2,s,2) on conflict(issuer_id,environment,series) do update set next_number=nfse_sequences.next_number+1 returning next_number-1 into v; update nfse_invoices set series=s,dps_number=v,status='queued' where id=invoice; return query select s,v; end $$;
revoke all on function reserve_nfse_dps(uuid) from public,anon; grant execute on function reserve_nfse_dps(uuid) to authenticated;
create or replace function claim_nfse_jobs(worker text,batch int default 10) returns setof nfse_jobs language sql security definer set search_path=public,pg_temp as $$ update nfse_jobs j set status='claimed',claimed_by=worker,lease_until=now()+interval '60 seconds',attempts=attempts+1 where j.id in(select id from nfse_jobs where status='queued' and available_at<=now() order by created_at for update skip locked limit least(greatest(batch,1),50)) returning j.* $$;
revoke all on function claim_nfse_jobs(text,int) from public,anon,authenticated; grant execute on function claim_nfse_jobs(text,int) to service_role;
do $$ declare t text; begin foreach t in array array['nfse_issuers','nfse_profile_issuer_access','nfse_service_profiles','nfse_takers','nfse_certificates','nfse_sequences','nfse_invoices','nfse_jobs','nfse_attempts','nfse_files'] loop execute format('alter table %I enable row level security',t); if t<>'nfse_profile_issuer_access' then execute format('create policy isolate_%I on %I for all to authenticated using(office_id=current_office() and has_module(''nfse'')) with check(office_id=current_office() and has_module(''nfse''))',t,t); end if; end loop; end $$;
create index nfse_invoice_list on nfse_invoices(office_id,issuer_id,competence desc,status); create index nfse_job_claim on nfse_jobs(status,available_at,created_at);
insert into storage.buckets(id,name,public,file_size_limit) values('nfse-custody','nfse-custody',false,8000000) on conflict(id) do nothing;
insert into storage.buckets(id,name,public,file_size_limit) values('nfse-documents','nfse-documents',false,10000000) on conflict(id) do nothing;
